// BMPImageWriter implements image.Writer interface, it writes BMP format
type BMPImageWriter struct{}

// WriteImage writes an image represented by byte slice into file with BMP format.
func (writer BMPImageWriter) WriteImage(filename string, img image.Image) error {
	file, err := os.Create(filename)
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()

	bounds := img.Bounds()
	width := bounds.Max.X - bounds.Min.X
	height := bounds.Max.Y - bounds.Min.Y

	bmpHeader := []byte{
		/* BMP header structure: */
		0x42, 0x4d, /* magic number */
		0x46, 0x00, 0x00, 0x00, /* size of header=70 bytes */
		0x00, 0x00, /* unused */
		0x00, 0x00, /* unused */
		0x36, 0x00, 0x00, 0x00, /* 54 bytes - offset to data */
		0x28, 0x00, 0x00, 0x00, /* 40 bytes - bytes in DIB header */
		0x00, 0x00, 0x00, 0x00, /* width of bitmap */
		0x00, 0x00, 0x00, 0x00, /* height of bitmap */
		0x01, 0x0, /* 1 pixel plane */
		0x18, 0x00, /* 24 bpp */
		0x00, 0x00, 0x00, 0x00, /* no compression */
		0x00, 0x00, 0x00, 0x00, /* size of pixel array */
		0x13, 0x0b, 0x00, 0x00, /* 2835 pixels/meter */
		0x13, 0x0b, 0x00, 0x00, /* 2835 pixels/meter */
		0x00, 0x00, 0x00, 0x00, /* color palette */
		0x00, 0x00, 0x00, 0x00, /* important colors */
	}

	bmpHeader[18] = byte(width & 0xff)
	bmpHeader[19] = byte(width >> 8)
	bmpHeader[20] = byte(width >> 16)
	bmpHeader[21] = byte(width >> 24)
	bmpHeader[22] = byte(height & 0xff)
	bmpHeader[23] = byte(height >> 8)
	bmpHeader[24] = byte(height >> 16)
	bmpHeader[25] = byte(height >> 24)

	file.Write(bmpHeader)

	for y := range height {
		for x := range width {
			r, g, b, _ := img.At(x, y).RGBA()
			// swap RGB
			color := []byte{byte(b >> 8), byte(g >> 8), byte(r >> 8)}
			file.Write(color)
		}
	}
	// no error
	return nil
}

// NewBMPImageWriter is a constructor for BMP image writer
func NewBMPImageWriter() BMPImageWriter {
	return BMPImageWriter{}
}

// PPMImageWriter implements image.Writer interface, it writes into selected PPM format
type PPMImageWriter struct{}

// WritePPMImage writes an image represented by standard image.Image structure into file with PPM format.
func (writer PPMImageWriter) WriteImage(filename string, img image.Image) error {
	file, err := os.Create(filename)
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()

	bounds := img.Bounds()
	width := bounds.Max.X - bounds.Min.X
	height := bounds.Max.Y - bounds.Min.Y

	fmt.Fprintln(file, "P3")
	fmt.Fprintf(file, "%d %d\n", width, height)
	fmt.Fprintln(file, "255")

	for y := range height {
		for x := range width {
			r, g, b, _ := img.At(x, y).RGBA()
			fmt.Fprintf(file, "%d %d %d\n", r>>8, g>>8, b>>8)
		}
	}
	return nil
}

// NewPPMImageWriter is a constructor for PPM image writer
func NewPPMImageWriter() PPMImageWriter {
	return PPMImageWriter{}
}

// TGAImageWriter implements image.Writer interface, it writes TGA format
type TGAImageWriter struct{}

// WriteTGAImage writes an image represented by byte slice into file with TGA format.
func (writer TGAImageWriter) WriteImage(filename string, img image.Image) error {
	file, err := os.Create(filename)
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()

	bounds := img.Bounds()
	width := bounds.Max.X - bounds.Min.X
	height := bounds.Max.Y - bounds.Min.Y

	tgaHeader := []byte{
		/* TGA header structure: */
		0x00,       /* without image ID */
		0x00,       /* color map type: without palette */
		0x02,       /* uncompressed true color image */
		0x00, 0x00, /* start of color palette (it is not used) */
		0x00, 0x00, /* length of color palette (it is not used) */
		0x00,                   /* bits per palette entry */
		0x00, 0x00, 0x00, 0x00, /* image coordinates */
		0x00, 0x00, /* image width */
		0x00, 0x00, /* image height */
		0x18, /* bits per pixel = 24 */
		0x20, /* picture orientation: top-left origin */
	}

	/* image size is specified in TGA header */
	tgaHeader[12] = byte(width & 0xff)
	tgaHeader[13] = byte(width >> 8)
	tgaHeader[14] = byte(height & 0xff)
	tgaHeader[15] = byte(height >> 8)

	file.Write(tgaHeader)

	for y := range height {
		for x := range width {
			r, g, b, _ := img.At(x, y).RGBA()
			// swap RGB
			color := []byte{byte(b >> 8), byte(g >> 8), byte(r >> 8)}
			file.Write(color)
		}
	}
	// no error
	return nil
}

// NewTGAImageWriter is a constructor for TGA image writer
func NewTGAImageWriter() TGAImageWriter {
	return TGAImageWriter{}
}

type Float32Node struct {
	Value float32
	Left  *Float32Node
	Right *Float32Node
}

type Float32BinaryTree struct {
	Root *Float32Node
}

func (bt *Float32BinaryTree) Insert(value float32) {
	node := &Float32Node{value, nil, nil}
	if bt.Root == nil {
		bt.Root = node
	} else {
		insertFloat32Node(bt.Root, node)
	}
}

func insertFloat32Node(node, newNode *Float32Node) {
	if newNode.Value < node.Value {
		if node.Left == nil {
			node.Left = newNode
		} else {
			insertFloat32Node(node.Left, newNode)
		}
	} else {
		if node.Right == nil {
			node.Right = newNode
		} else {
			insertFloat32Node(node.Right, newNode)
		}
	}
}

func printFloat32Tree(node *Float32Node, level int) {
	if node != nil {
		format := ""
		for i := 0; i < level; i++ {
			format += "       "
		}
		format += "---[ "
		level++
		printFloat32Tree(node.Left, level)
		fmt.Printf(format+"%v\n", node.Value)
		printFloat32Tree(node.Right, level)
	}
}

