// CalcZPowerMandelbrot calculates Mandelbrot set into the provided ZPixels
// Calculations use complex numbers
func A2CalcZPowerMandelbrot(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	var cy float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var cx float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			c := complex(cx, cy)
			z := complex(cx, cy)
			var i uint
			for i < params.Maxiter {
				zx := real(z)
				zy := imag(z)
				if zx*zx+zy*zy > float64(params.Bailout) {
					break
				}
				z = cmplx.Pow(z, z) + z*z + c
				i++
			}
			image.Z[y][x] = ZPixel(z)
			image.I[y][x] = IPixel(calcIndex(params, i))
			cx += stepX
		}
		cy += stepY
	}
}

// CalcBarnsleyJuliaJ1 calculates Barnsley J1 Mandelbrot-like set
func A3CalcBarnsleyJuliaJ1(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	cx := params.Cx0
	cy := params.Cy0
	var zy0 float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var zx0 float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			var zx float64 = zx0
			var zy float64 = zy0
			var i uint
			for i < params.Maxiter {
				var zxn float64
				var zyn float64
				zx2 := zx * zx
				zy2 := zy * zy
				if zx2+zy2 > float64(params.Bailout) {
					break
				}
				if zx >= 0 {
					zxn = zx*cx - zy*cy - cx
					zyn = zx*cy + zy*cx - cy
				} else {
					zxn = zx*cx - zy*cy + cx
					zyn = zx*cy + zy*cx + cy
				}
				zx = zxn
				zy = zyn
				i++
			}
			image.Z[y][x] = ZPixel(complex(zx, zy))
			image.I[y][x] = IPixel(calcIndex(params, i))
			zx0 += stepX
		}
		zy0 += stepY
	}
}

