// CalcMandelbrotFn calculates Mandelbrot set into the provided ZPixels
func A8CalcMandelbrotFn(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	var cy float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var cx float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			c := complex(cx, cy)
			z := c
			var i uint
			for i < params.Maxiter {
				zx := real(z)
				zy := imag(z)
				if zx*zx+zy*zy > float64(params.Bailout) {
					break
				}
				z = c * cmplx.Sin(z)
				i++
			}
			image.Z[y][x] = ZPixel(z)
			image.I[y][x] = IPixel(i)
			cx += stepX
		}
		cy += stepY
	}
}

// CalcManowarM calculates Manowar Mandelbrot-like set
func A8CalcManowarM(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	var cy float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var cx float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			var c complex128 = complex(cx, cy)
			var z = c
			var z1 = c
			var i uint
			for i < params.Maxiter {
				zx := real(z)
				zy := imag(z)
				if zx*zx+zy*zy > 4.0 {
					break
				}
				z2 := z*z + z1 + c
				z1 = z
				z = z2
				i++
			}
			image.Z[y][x] = ZPixel(z)
			image.I[y][x] = IPixel(calcIndex(params, i))
			cx += stepX
		}
		cy += stepY
	}
}

// CalcManowarJ calculates Manowar Julia-like set
func A8CalcManowarJ(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	cx := params.Cx0
	cy := params.Cy0
	var c complex128 = complex(cx, cy)

	var zy0 float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var zx0 float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			var z complex128 = complex(zx0, zy0)
			var z1 = z
			var i uint
			for i < params.Maxiter {
				zx := real(z)
				zy := imag(z)
				if zx*zx+zy*zy > 4.0 {
					break
				}
				z2 := z*z + z1 + c
				z1 = z
				z = z2
				i++
			}
			i *= 3
			image.Z[y][x] = ZPixel(z)
			image.I[y][x] = IPixel(calcIndex(params, i))
			zx0 += stepX
		}
		zy0 += stepY
	}
}

// CalcNewton calculates Newton fractal
func A8CalcNewton(
	params FractalParameter,
	image Image) {

	const Epsilon = 0.001

	var RootX1 = 1.0
	var RootY1 = 0.0

	var RootX2 = -0.5
	var RootY2 = math.Sqrt(3) / 2

	var RootX3 = -0.5
	var RootY3 = -math.Sqrt(3) / 2

	stepX, stepY := getSteps(params, image)

	var zy0 float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var zx0 float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			zx := zx0
			zy := zy0
			i := uint(0)

			for i < params.Maxiter {
				zx2 := zx * zx
				zy2 := zy * zy
				zxn := 2.0/3.0*zx + (zx2-zy2)/(3.0*(zx2*zx2+zy2*zy2+2.0*zx2*zy2))
				zyn := 2.0/3.0*zy - 2.0*zx*zy/(3.0*(zx2*zx2+zy2*zy2+2.0*zx2*zy2))
				zx = zxn
				zy = zyn
				if math.Hypot(zx-RootX1, zy-RootY1) < Epsilon {
					break
				}
				if math.Hypot(zx-RootX2, zy-RootY2) < Epsilon {
					i += 128
					break
				}
				if math.Hypot(zx-RootX3, zy-RootY3) < Epsilon {
					i += 192
					break
				}
				i++
			}
			image.Z[y][x] = ZPixel(complex(zx, zy))
			image.I[y][x] = IPixel(calcIndex(params, i))
			zx0 += stepX
		}
		zy0 += stepY
	}
}

// CalcPhoenixJ calculates Phoenix Julia-like set
func A8CalcPhoenixJ(
	params FractalParameter,
	image Image) {

	stepX, stepY := getSteps(params, image)

	cx := params.Cx0
	cy := params.Cy0

	var zy0 float64 = params.Ymin
	for y := uint(0); y < image.Resolution.Height; y++ {
		var zx0 float64 = params.Xmin
		for x := uint(0); x < image.Resolution.Width; x++ {
			var zx float64 = zx0
			var zy float64 = zy0
			var ynx = 0.0
			var yny = 0.0
			var i uint
			for i < params.Maxiter {
				zx2 := zx * zx
				zy2 := zy * zy
				zxn := zx2 - zy2 + cx + cy*ynx
				zyn := 2.0*zx*zy + cy*yny
				if zx2+zy2 > float64(params.Bailout) {
					break
				}
				ynx = zx
				yny = zy
				zx = zxn
				zy = zyn
				i++
			}
			image.Z[y][x] = ZPixel(complex(zx, zy))
			image.I[y][x] = IPixel(calcIndex(params, i))
			zx0 += stepX
		}
		zy0 += stepY
	}
}

